CREATE OR REPLACE FUNCTION public.my_take_invoice_state(p_visit_id uuid)
 RETURNS TABLE(state text, refusal_reason text, amount_chf numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
